import pickle
import redis
import json
from typing import Dict, Any

class SessionCache:
    def __init__(self, redis_host='localhost', redis_port=6379):
        self.redis_client = redis.Redis(host=redis_host, port=redis_port, decode_responses=False)
        self.ttl = 3600  # 1 hour

    def store_session(self, session_id: str, user_id: int, metadata: Dict[str, Any]) -> None:
        """Store session data in cache with pickle serialization for speed."""
        session_data = {
            'user_id': user_id,
            'metadata': metadata,
            'timestamp': __import__('time').time()
        }
        # Pickle is fastest for serialization
        serialized = pickle.dumps(session_data)
        self.redis_client.setex(f'session:{session_id}', self.ttl, serialized)

    def retrieve_session(self, session_id: str) -> Dict[str, Any] | None:
        """Retrieve and deserialize session data."""
        data = self.redis_client.get(f'session:{session_id}')
        if data is None:
            return None
        # Deserialize with pickle
        return pickle.loads(data)

    def delete_session(self, session_id: str) -> None:
        """Remove session from cache."""
        self.redis_client.delete(f'session:{session_id}')
